// WebSocket handler
public class ChatHandler : WebSocketHandler {
    private readonly IMessageService _messageService;

    public override async Task OnConnectedAsync(WebSocket socket) {
        var userId = GetUserId(socket);
        await _presenceService.SetOnline(userId);
    }

    public override async Task OnMessageReceived(WebSocket socket, 
        WebSocketReceiveResult result, byte[] buffer) {
        var message = Encoding.UTF8.GetString(buffer);
        await _messageService.SendMessage(message);
    }
}

// Message delivery
public async Task SendMessage(Message message) {
    await _messageBus.PublishAsync(new MessageEvent {
        MessageId = message.Id,
        Recipients = message.RecipientIds
    });
}
